#!/usr/bin/env python3
"""mld-snoop-decode 端到端冒烟测试（临时，不入库）。"""

import ipaddress
import json
import os
import subprocess
import sys
import tempfile
import unittest
import zlib

HERE = os.path.dirname(os.path.abspath(__file__))
SWITCH = os.path.join(HERE, "switch.py")


def internet_checksum(data):
    if len(data) % 2:
        data = data + b"\x00"
    total = 0
    for index in range(0, len(data), 2):
        total += (data[index] << 8) | data[index + 1]
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    return (~total) & 0xFFFF


def v6(addr):
    return ipaddress.IPv6Address(addr).packed


def icmpv6(mtype, rest, src, dst, bad=False):
    """rest 为 code/checksum 之后的报文体；checksum 在 [2:4]。"""
    body = bytes([mtype, 0, 0, 0]) + bytes(rest)
    pseudo = (
        v6(src) + v6(dst) + len(body).to_bytes(4, "big")
        + b"\x00\x00\x00\x3a"
    )
    cksum = internet_checksum(pseudo + body)
    if bad:
        cksum ^= 0xFFFF
    return body[:2] + cksum.to_bytes(2, "big") + body[4:]


def hop_ext(next_header=58, ra_value=b"\x00\x00", include_ra=True,
            ra_type=5, ra_len=2, malformed=False):
    if malformed:
        options = b"\x01\x04\x00"  # PadN 声称 4 字节但被截断
    else:
        options = b""
        if include_ra:
            options += bytes([ra_type, ra_len]) + ra_value
    options += b"\x00" * (6 - len(options))
    return bytes([next_header, 0]) + options


def v6_envelope(src, dst, ext, body, hop=1, payload_len=None):
    pl = payload_len if payload_len is not None else len(ext) + len(body)
    head = (
        bytes([0x60, 0, 0, 0]) + pl.to_bytes(2, "big") + bytes([0, hop])
        + v6(src) + v6(dst)
    )
    pad = b"\x00" * max(0, 46 - len(ext) - len(body))
    return head + ext + body + pad


def mld_v1_frame(mtype, group, dst_group, src="fe80::1", hop=1, bad=False,
                 payload_len=None, **ext_kw):
    body = icmpv6(mtype, b"\x00\x00\x00\x00" + v6(group), src, dst_group,
                  bad=bad)
    ext = hop_ext(**ext_kw) if ext_kw.get("use_hop", True) else b""
    return v6_envelope(src, dst_group, ext, body, hop=hop,
                       payload_len=payload_len)


def v2_records_body(records):
    out = b""
    for rtype, group, sources in records:
        out += (
            bytes([rtype, 0]) + len(sources).to_bytes(2, "big") + v6(group)
            + b"".join(v6(s) for s in sources)
        )
    return out


def mld_v2_frame(records, src="fe80::2", dst="ff02::16", bad=False,
                 count=None, append=b"", truncate=0):
    number = len(records) if count is None else count
    rest = b"\x00\x00" + number.to_bytes(2, "big") + v2_records_body(records)
    rest += append
    body = icmpv6(143, rest, src, dst, bad=bad)
    if truncate:
        body = body[:-truncate]
    return v6_envelope(src, dst, hop_ext(), body)


def data_frame_v6(group, src="2001:db8::9", udp_len=8):
    payload = b"\x00" * udp_len
    head = (
        bytes([0x60, 0, 0, 0]) + (40 + len(payload)).to_bytes(2, "big")
        + bytes([17, 64]) + v6(src) + v6(group)
    )
    return head + payload + b"\x00" * max(0, 46 - len(payload))


def group_mac(group):
    g = v6(group)
    return "33:33:%02x:%02x:%02x:%02x" % tuple(g[12:16])


def raw_frame(t, port, dst, src, payload, vlan=None, ethertype=0x86DD,
              bad_fcs=False):
    d = bytes(int(x, 16) for x in dst.split(":"))
    s = bytes(int(x, 16) for x in src.split(":"))
    if vlan is None:
        head = d + s + ethertype.to_bytes(2, "big")
    else:
        head = (
            d + s + b"\x81\x00" + vlan.to_bytes(2, "big")
            + ethertype.to_bytes(2, "big")
        )
    body = head + payload
    fcs = (zlib.crc32(body) & 0xFFFFFFFF).to_bytes(4, "little")
    if bad_fcs:
        fcs = b"\xff\xff\xff\xff"
    return {"t": t, "port": port, "data": (body + fcs).hex()}


def make_port(name, mode="trunk", pvid=1, allowed=None, untagged=None,
              up=True):
    if allowed is None:
        allowed = [pvid]
    if untagged is None:
        untagged = [] if mode == "trunk" else [pvid]
    return {
        "name": name, "mode": mode, "pvid": pvid, "allowed": allowed,
        "untagged": untagged, "up": up,
    }


def make_config(router_ports=("p1",), membership_age=50):
    return {
        "bridges": ["b1"], "links": [], "delay": 2, "bridge": "b1",
        "ports": [
            make_port("p1", allowed=[1, 2]),
            make_port("p2", allowed=[1, 2]),
            make_port("p3", allowed=[1, 2]),
            make_port("p4", mode="hybrid", allowed=[1, 2], untagged=[1]),
        ],
        "age": 100, "max_frame": 1518,
        "mld": {"membership_age": membership_age,
                "router_ports": list(router_ports)},
    }


G1 = "ff0e::1234"
G2 = "ff0e::5"


class MldCase(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        d = self.tmp.name
        self.cfg = os.path.join(d, "config.json")
        self.evt = os.path.join(d, "events.json")
        self.log = os.path.join(d, "out.log")

    def tearDown(self):
        self.tmp.cleanup()

    def write(self, config, events):
        with open(self.cfg, "wb") as h:
            h.write(json.dumps(config).encode())
        with open(self.evt, "wb") as h:
            h.write(json.dumps(events).encode())

    def run_cmd(self, *args):
        p = subprocess.run([sys.executable, SWITCH, *args],
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        return p.returncode, p.stdout, p.stderr

    def simulate(self, config, events):
        self.write(config, events)
        code, out, err = self.run_cmd("mld-snoop-decode", self.cfg, self.evt)
        self.assertEqual(code, 0, err)
        return json.loads(out.decode())

    def report(self, t, port, group=G1, vlan=1, **kw):
        return raw_frame(t, port, group_mac(group), "02:00:00:00:00:01",
                         mld_v1_frame(131, group, group, **kw), vlan=vlan)

    def done(self, t, port, group=G1, vlan=1, **kw):
        return raw_frame(t, port, group_mac("ff02::2"), "02:00:00:00:00:01",
                         mld_v1_frame(132, group, "ff02::2", **kw), vlan=vlan)

    def query(self, t, port, group=G1, vlan=1, **kw):
        return raw_frame(t, port, group_mac("ff02::1"), "02:00:00:00:00:fe",
                         mld_v1_frame(130, group, "ff02::1", **kw), vlan=vlan)

    def data_frame(self, t, port, group=G1, src="2001:db8::9", vlan=1,
                   dst_mac=None):
        return raw_frame(t, port, dst_mac or group_mac(group),
                         "02:00:00:00:00:09", data_frame_v6(group, src),
                         vlan=vlan)

    def v2(self, t, port, records, vlan=1, **kw):
        return raw_frame(t, port, "33:33:00:00:00:16", "02:00:00:00:00:02",
                         mld_v2_frame(records, **kw), vlan=vlan)


class MldControlTest(MldCase):
    def test_report_to_router_and_delivery(self):
        events = [self.report(1, "p2"), self.data_frame(2, "p3")]
        r = self.simulate(make_config(), events)
        self.assertEqual(
            [(x["t"], x["action"]) for x in r["results"]],
            [(1, "mld_report"), (2, "multicast")],
        )
        self.assertEqual(r["results"][0]["ports"], [{"name": "p1", "vlan": 1}])
        self.assertEqual(
            [p["name"] for p in r["results"][1]["ports"]], ["p1", "p2"]
        )
        self.assertEqual(r["groups"][0]["group"], "ff0e::1234")
        self.assertEqual(
            r["groups"][0]["members"], [{"name": "p2", "expires": 51}]
        )

    def test_report_flood_without_router(self):
        r = self.simulate(make_config(router_ports=()), [self.report(1, "p2")])
        self.assertEqual(r["results"][0]["action"], "mld_report")
        self.assertEqual(
            [p["name"] for p in r["results"][0]["ports"]],
            ["p1", "p3", "p4"],
        )

    def test_ingress_router_excluded(self):
        r = self.simulate(make_config(router_ports=("p2",)),
                          [self.report(1, "p2")])
        self.assertEqual(
            [p["name"] for p in r["results"][0]["ports"]],
            ["p1", "p3", "p4"],
        )

    def test_query_floods_general_and_specific(self):
        r = self.simulate(make_config(), [self.query(1, "p2")])
        self.assertEqual(r["results"][0]["action"], "mld_query")
        self.assertEqual(
            [p["name"] for p in r["results"][0]["ports"]],
            ["p1", "p3", "p4"],
        )
        self.assertEqual(r["groups"], [])
        r = self.simulate(
            make_config(), [self.query(1, "p2", group="::")]
        )
        self.assertEqual(r["results"][0]["action"], "mld_query")

    def test_done_deletes_member(self):
        events = [
            self.report(1, "p2"),
            self.done(2, "p2"),
            self.data_frame(3, "p3"),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(
            [x["action"] for x in r["results"]],
            ["mld_report", "mld_done", "flood"],
        )
        self.assertEqual(r["results"][1]["ports"], [{"name": "p1", "vlan": 1}])
        self.assertEqual(r["groups"], [])

    def test_aging(self):
        events = [
            self.report(1, "p2"),
            self.data_frame(50, "p3"),
            self.data_frame(51, "p3"),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(
            [x["action"] for x in r["results"][1:]],
            ["multicast", "flood"],
        )

    def test_bad_mapping_flood(self):
        events = [
            self.report(1, "p2"),
            self.data_frame(2, "p3", dst_mac="33:33:ff:00:00:01"),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][1]["action"], "flood")

    def test_groups_sorted_and_compressed(self):
        events = [
            self.report(1, "p3", "ff02::1:ff00:1"),
            self.report(2, "p2", "ff02::1"),
            raw_frame(
                3, "p2", group_mac("ff1e::abcd"), "02:00:00:00:00:01",
                mld_v1_frame(131, "ff1e::abcd", "ff1e::abcd"), vlan=2,
            ),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(
            [(g["vlan"], g["group"]) for g in r["groups"]],
            [(1, "ff02::1"), (1, "ff02::1:ff00:1"), (2, "ff1e::abcd")],
        )

    def test_output_key_order(self):
        self.write(make_config(), [self.report(1, "p2")])
        code, out, err = self.run_cmd("mld-snoop-decode", self.cfg, self.evt)
        self.assertEqual(code, 0, err)
        text = out.decode()
        self.assertIn(
            '"results":[{"t":1,"class":"good","action":"mld_report",'
            '"ports":[{"name":"p1","vlan":1}]',
            text,
        )
        result = json.loads(text)
        self.assertEqual(list(result), ["results", "ports", "vlans", "groups"])
        self.assertEqual(list(result["groups"][0]),
                         ["vlan", "group", "members"])


class MldInvalidTest(MldCase):
    def test_bad_checksum_invalid(self):
        events = [
            raw_frame(
                1, "p2", group_mac(G1), "02:00:00:00:00:01",
                mld_v1_frame(131, G1, G1, bad=True),
            ),
            self.data_frame(2, "p3"),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][0]["action"], "mld_invalid")
        self.assertEqual(r["results"][0]["ports"], [])
        self.assertEqual(r["results"][1]["action"], "flood")
        self.assertEqual(r["groups"], [])
        self.assertEqual(r["ports"][1]["drop"], 1)
        self.assertEqual(r["vlans"][0]["drop"], 1)

    def test_hop_limit_not_one_invalid(self):
        events = [
            raw_frame(
                1, "p2", group_mac(G1), "02:00:00:00:00:01",
                mld_v1_frame(131, G1, G1, hop=64),
            ),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][0]["action"], "mld_invalid")

    def test_no_router_alert_not_recognized(self):
        events = [
            raw_frame(
                1, "p2", group_mac(G1), "02:00:00:00:00:01",
                mld_v1_frame(131, G1, G1, include_ra=False),
            ),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][0]["action"], "flood")

    def test_ra_value_non_mld_not_recognized(self):
        events = [
            raw_frame(
                1, "p2", group_mac(G1), "02:00:00:00:00:01",
                mld_v1_frame(131, G1, G1, ra_value=b"\x00\x01"),
            ),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][0]["action"], "flood")

    def test_non_icmpv6_not_recognized(self):
        events = [
            raw_frame(
                1, "p2", group_mac(G1), "02:00:00:00:00:01",
                mld_v1_frame(131, G1, G1, next_header=17),
            ),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][0]["action"], "flood")

    def test_bad_group_invalid(self):
        events = [
            raw_frame(
                1, "p2", group_mac("2001:db8::1"), "02:00:00:00:00:01",
                mld_v1_frame(131, "2001:db8::1", "2001:db8::1"),
            ),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][0]["action"], "mld_invalid")

    def test_query_bad_group_invalid(self):
        events = [
            raw_frame(
                1, "p2", group_mac("ff02::1"), "02:00:00:00:00:fe",
                mld_v1_frame(130, "2001:db8::1", "ff02::1"),
            ),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][0]["action"], "mld_invalid")

    def test_unspecified_src_invalid(self):
        events = [
            raw_frame(
                1, "p2", group_mac(G1), "02:00:00:00:00:01",
                mld_v1_frame(131, G1, G1, src="::"),
            ),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][0]["action"], "mld_invalid")

    def test_payload_boundary_invalid(self):
        events = [
            raw_frame(
                1, "p2", group_mac(G1), "02:00:00:00:00:01",
                mld_v1_frame(131, G1, G1, payload_len=200),
            ),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][0]["action"], "mld_invalid")

    def test_bad_v1_length_invalid(self):
        # 23-byte body
        body = icmpv6(131, b"\x00\x00\x00\x00" + v6(G1)[:-1], "fe80::1", G1)
        payload = v6_envelope("fe80::1", G1, hop_ext(), body)
        events = [
            raw_frame(1, "p2", group_mac(G1), "02:00:00:00:00:01", payload),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][0]["action"], "mld_invalid")

    def test_nonzero_code_invalid(self):
        body = bytearray(icmpv6(131, b"\x00\x00\x00\x00" + v6(G1),
                                "fe80::1", G1))
        body[1] = 1
        # 重算校验和
        pseudo = (
            v6("fe80::1") + v6(G1) + len(body).to_bytes(4, "big")
            + b"\x00\x00\x00\x3a"
        )
        zero = bytes(body[:2]) + b"\x00\x00" + bytes(body[4:])
        cksum = internet_checksum(pseudo + zero)
        body[2:4] = cksum.to_bytes(2, "big")
        payload = v6_envelope("fe80::1", G1, hop_ext(), bytes(body))
        events = [
            raw_frame(1, "p2", group_mac(G1), "02:00:00:00:00:01", payload),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][0]["action"], "mld_invalid")


class MldV2Test(MldCase):
    S1 = "2001:db8::9"
    S2 = "2001:db8::10"

    def test_include_filter(self):
        events = [
            self.v2(1, "p2", [(1, G1, [self.S1])]),
            self.data_frame(2, "p3", src=self.S1),
            self.data_frame(3, "p3", src=self.S2),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][0]["action"], "mldv2_report")
        self.assertEqual(
            [p["name"] for p in r["results"][1]["ports"]], ["p1", "p2"]
        )
        self.assertEqual(
            [p["name"] for p in r["results"][2]["ports"]], ["p1"]
        )

    def test_empty_include_deletes(self):
        events = [
            self.v2(1, "p2", [(1, G1, [self.S1])]),
            self.v2(2, "p2", [(1, G1, [])]),
            self.data_frame(3, "p3", src=self.S1),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][2]["action"], "flood")
        self.assertEqual(r["groups"], [])

    def test_exclude_all_sources(self):
        events = [
            self.v2(1, "p2", [(2, G1, [])]),
            self.data_frame(2, "p3", src=self.S2),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(
            [p["name"] for p in r["results"][1]["ports"]], ["p1", "p2"]
        )

    def test_six_records_allow_block(self):
        events = [
            self.v2(1, "p2", [(1, G1, [self.S1])]),
            self.v2(2, "p2", [(5, G1, [self.S2])]),
            self.v2(3, "p2", [(4, G1, [self.S1])]),
            self.v2(4, "p2", [(6, G1, [self.S2])]),
        ]
        r = self.simulate(make_config(), events)
        m = r["groups"][0]["members"][0]
        self.assertEqual(m["mode"], "exclude")
        self.assertEqual(m["sources"], ["2001:db8::10"])
        self.assertEqual(list(m), ["name", "expires", "mode", "sources"])

    def test_mode_is_exclude_and_change_to_include(self):
        events = [
            self.v2(1, "p2", [(2, G1, [self.S1])]),
            self.v2(2, "p2", [(3, G1, [self.S2])]),
        ]
        r = self.simulate(make_config(membership_age=50), events)
        self.assertEqual(
            r["groups"][0]["members"],
            [{"name": "p2", "expires": 52, "mode": "include",
              "sources": ["2001:db8::10"]}],
        )

    def test_sources_sorted_numeric_and_compressed(self):
        events = [
            self.v2(1, "p2",
                    [(1, G1, ["fe80::2", "2001:db8::1", self.S1])]),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(
            r["groups"][0]["members"][0]["sources"],
            ["fe80::2", "2001:db8::1", "2001:db8::9"],
        )

    def test_invalid_record_no_commit(self):
        events = [
            self.v2(1, "p2", [(1, G2, [self.S1])]),
            self.v2(2, "p2", [(1, G1, [self.S1]), (1, G1, ["::"])]),
            self.data_frame(3, "p3", src=self.S1),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][1]["action"], "mld_invalid")
        self.assertEqual(r["results"][2]["action"], "flood")
        self.assertEqual([g["group"] for g in r["groups"]], [G2])

    def test_bad_record_type(self):
        r = self.simulate(make_config(), [self.v2(1, "p2", [(7, G1, [])])])
        self.assertEqual(r["results"][0]["action"], "mld_invalid")

    def test_multicast_source_invalid(self):
        r = self.simulate(
            make_config(), [self.v2(1, "p2", [(1, G1, ["ff02::9"])])]
        )
        self.assertEqual(r["results"][0]["action"], "mld_invalid")

    def test_count_mismatch(self):
        r = self.simulate(
            make_config(), [self.v2(1, "p2", [(1, G1, [])], count=2)]
        )
        self.assertEqual(r["results"][0]["action"], "mld_invalid")

    def test_truncated_invalid(self):
        r = self.simulate(
            make_config(),
            [self.v2(1, "p2", [(1, G1, [self.S1])], truncate=2)],
        )
        self.assertEqual(r["results"][0]["action"], "mld_invalid")

    def test_v1_and_v2_coexist(self):
        events = [self.report(1, "p3"),
                  self.v2(2, "p2", [(2, G1, [self.S1])])]
        r = self.simulate(make_config(membership_age=50), events)
        members = r["groups"][0]["members"]
        self.assertEqual([m["name"] for m in members], ["p2", "p3"])
        self.assertEqual(list(members[0]),
                         ["name", "expires", "mode", "sources"])
        self.assertEqual(list(members[1]), ["name", "expires"])


class MldRecordTest(MldCase):
    def test_record_replay_byte_identical(self):
        events = [self.report(1, "p2"), self.data_frame(2, "p3")]
        self.write(make_config(), events)
        code, direct, err = self.run_cmd(
            "mld-snoop-decode", self.cfg, self.evt
        )
        self.assertEqual(code, 0, err)
        rec = subprocess.run(
            [sys.executable, SWITCH, "record", self.cfg, self.evt, self.log],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
        )
        self.assertEqual(rec.returncode, 0, rec.stderr)
        self.assertEqual(rec.stdout, direct)
        code, out, err = self.run_cmd("replay", self.log)
        self.assertEqual((code, out, err), (0, direct, b""))
        with open(self.log, "rb") as h:
            doc = json.loads(h.read().decode())
        self.assertEqual(doc["config"]["mld"]["router_ports"], ["p1"])

    def test_work_boundary(self):
        # B=1 L=0 P=4: stp 部分 1+5+6=12；N*(N+P+1)=2*7=14；合计 26
        events = [self.report(1, "p2"), self.data_frame(2, "p3")]
        self.write(make_config(), events)
        head = ("1048576", "16777216", "100000", "16777216")
        code, _, err = self.run_cmd(
            "mld-snoop-decode", self.cfg, self.evt, *head, "26"
        )
        self.assertEqual(code, 0, err)
        code, out, err = self.run_cmd(
            "mld-snoop-decode", self.cfg, self.evt, *head, "25"
        )
        self.assertEqual(code, 5)
        self.assertEqual(out, b"")
        self.assertEqual(err, b'{"error":"mld_work_limit"}\n')

    def test_bad_config_exit_4(self):
        bad = make_config()
        bad["mld"] = {"membership_age": 0, "router_ports": ["p1"]}
        self.write(bad, [])
        code, out, err = self.run_cmd("mld-snoop-decode", self.cfg, self.evt)
        self.assertEqual((code, out), (4, b""))
        self.assertEqual(err, b'{"error":"invalid_input"}\n')

    def test_record_bad_config_no_log(self):
        bad = make_config()
        bad["mld"] = {"membership_age": -1, "router_ports": ["p1"]}
        self.write(bad, [])
        code, out, err = self.run_cmd("record", self.cfg, self.evt, self.log)
        self.assertEqual((code, out), (4, b""))
        self.assertFalse(os.path.exists(self.log))


if __name__ == "__main__":
    unittest.main()

