#!/usr/bin/env python3
"""mld-snoop-decode 端到端冒烟测试（临时，不入库）。"""

import ipaddress
import json
import os
import subprocess
import sys
import tempfile
import unittest
import zlib

HERE = os.path.dirname(os.path.abspath(__file__))
SWITCH = os.path.join(HERE, "switch.py")


def internet_checksum(data):
    if len(data) % 2:
        data = data + b"\x00"
    total = 0
    for index in range(0, len(data), 2):
        total += (data[index] << 8) | data[index + 1]
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    return (~total) & 0xFFFF


def v6(addr):
    return ipaddress.IPv6Address(addr).packed


def icmpv6(mtype, rest, src, dst, bad=False):
    """rest 为 code/checksum 之后的报文体；checksum 在 [2:4]。"""
    body = bytes([mtype, 0, 0, 0]) + bytes(rest)
    pseudo = (
        v6(src) + v6(dst) + len(body).to_bytes(4, "big")
        + b"\x00\x00\x00\x3a"
    )
    cksum = internet_checksum(pseudo + body)
    if bad:
        cksum ^= 0xFFFF
    return body[:2] + cksum.to_bytes(2, "big") + body[4:]


def hop_ext(next_header=58, ra_value=b"\x00\x00", include_ra=True,
            ra_type=5, ra_len=2, malformed=False):
    if malformed:
        options = b"\x01\x04\x00"  # PadN 声称 4 字节但被截断
    else:
        options = b""
        if include_ra:
            options += bytes([ra_type, ra_len]) + ra_value
    options += b"\x00" * (6 - len(options))
    return bytes([next_header, 0]) + options


def v6_envelope(src, dst, ext, body, hop=1, payload_len=None):
    pl = payload_len if payload_len is not None else len(ext) + len(body)
    head = (
        bytes([0x60, 0, 0, 0]) + pl.to_bytes(2, "big") + bytes([0, hop])
        + v6(src) + v6(dst)
    )
    pad = b"\x00" * max(0, 46 - len(ext) - len(body))
    return head + ext + body + pad


def mld_v1_frame(mtype, group, dst_group, src="fe80::1", hop=1, bad=False,
                 payload_len=None, **ext_kw):
    body = icmpv6(mtype, b"\x00\x00\x00\x00" + v6(group), src, dst_group,
                  bad=bad)
    ext = hop_ext(**ext_kw) if ext_kw.get("use_hop", True) else b""
    return v6_envelope(src, dst_group, ext, body, hop=hop,
                       payload_len=payload_len)


def v2_records_body(records):
    out = b""
    for rtype, group, sources in records:
        out += (
            bytes([rtype, 0]) + len(sources).to_bytes(2, "big") + v6(group)
            + b"".join(v6(s) for s in sources)
        )
    return out


def mld_v2_frame(records, src="fe80::2", dst="ff02::16", bad=False,
                 count=None, append=b"", truncate=0):
    number = len(records) if count is None else count
    rest = b"\x00\x00" + number.to_bytes(2, "big") + v2_records_body(records)
    rest += append
    body = icmpv6(143, rest, src, dst, bad=bad)
    if truncate:
        body = body[:-truncate]
    return v6_envelope(src, dst, hop_ext(), body)


def data_frame_v6(group, src="2001:db8::9", udp_len=8):
    payload = b"\x00" * udp_len
    head = (
        bytes([0x60, 0, 0, 0]) + (40 + len(payload)).to_bytes(2, "big")
        + bytes([17, 64]) + v6(src) + v6(group)
    )
    return head + payload + b"\x00" * max(0, 46 - len(payload))


def group_mac(group):
    g = v6(group)
    return "33:33:%02x:%02x:%02x:%02x" % tuple(g[12:16])


def raw_frame(t, port, dst, src, payload, vlan=None, ethertype=0x86DD,
              bad_fcs=False):
    d = bytes(int(x, 16) for x in dst.split(":"))
    s = bytes(int(x, 16) for x in src.split(":"))
    if vlan is None:
        head = d + s + ethertype.to_bytes(2, "big")
    else:
        head = (
            d + s + b"\x81\x00" + vlan.to_bytes(2, "big")
            + ethertype.to_bytes(2, "big")
        )
    body = head + payload
    fcs = (zlib.crc32(body) & 0xFFFFFFFF).to_bytes(4, "little")
    if bad_fcs:
        fcs = b"\xff\xff\xff\xff"
    return {"t": t, "port": port, "data": (body + fcs).hex()}


def make_port(name, mode="trunk", pvid=1, allowed=None, untagged=None,
              up=True):
    if allowed is None:
        allowed = [pvid]
    if untagged is None:
        untagged = [] if mode == "trunk" else [pvid]
    return {
        "name": name, "mode": mode, "pvid": pvid, "allowed": allowed,
        "untagged": untagged, "up": up,
    }


def make_config(router_ports=("p1",), membership_age=50):
    return {
        "bridges": ["b1"], "links": [], "delay": 2, "bridge": "b1",
        "ports": [
            make_port("p1", allowed=[1, 2]),
            make_port("p2", allowed=[1, 2]),
            make_port("p3", allowed=[1, 2]),
            make_port("p4", mode="hybrid", allowed=[1, 2], untagged=[1]),
        ],
        "age": 100, "max_frame": 1518,
        "mld": {"membership_age": membership_age,
                "router_ports": list(router_ports)},
    }


G1 = "ff0e::1234"
G2 = "ff0e::5"


class MldCase(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        d = self.tmp.name
        self.cfg = os.path.join(d, "config.json")
        self.evt = os.path.join(d, "events.json")
        self.log = os.path.join(d, "out.log")

    def tearDown(self):
        self.tmp.cleanup()

    def write(self, config, events):
        with open(self.cfg, "wb") as h:
            h.write(json.dumps(config).encode())
        with open(self.evt, "wb") as h:
            h.write(json.dumps(events).encode())

    def run_cmd(self, *args):
        p = subprocess.run([sys.executable, SWITCH, *args],
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        return p.returncode, p.stdout, p.stderr

    def simulate(self, config, events):
        self.write(config, events)
        code, out, err = self.run_cmd("mld-snoop-decode", self.cfg, self.evt)
        self.assertEqual(code, 0, err)
        return json.loads(out.decode())

    def report(self, t, port, group=G1, vlan=1, **kw):
        return raw_frame(t, port, group_mac(group), "02:00:00:00:00:01",
                         mld_v1_frame(131, group, group, **kw), vlan=vlan)

    def done(self, t, port, group=G1, vlan=1, **kw):
        return raw_frame(t, port, group_mac("ff02::2"), "02:00:00:00:00:01",
                         mld_v1_frame(132, group, "ff02::2", **kw), vlan=vlan)

    def query(self, t, port, group=G1, vlan=1, **kw):
        return raw_frame(t, port, group_mac("ff02::1"), "02:00:00:00:00:fe",
                         mld_v1_frame(130, group, "ff02::1", **kw), vlan=vlan)

    def data_frame(self, t, port, group=G1, src="2001:db8::9", vlan=1,
                   dst_mac=None):
        return raw_frame(t, port, dst_mac or group_mac(group),
                         "02:00:00:00:00:09", data_frame_v6(group, src),
                         vlan=vlan)

    def v2(self, t, port, records, vlan=1, **kw):
        return raw_frame(t, port, "33:33:00:00:00:16", "02:00:00:00:00:02",
                         mld_v2_frame(records, **kw), vlan=vlan)


