            ["fe80::2", "2001:db8::1", "2001:db8::9"],
        )

    def test_invalid_record_no_commit(self):
        events = [
            self.v2(1, "p2", [(1, G2, [self.S1])]),
            self.v2(2, "p2", [(1, G1, [self.S1]), (1, G1, ["::"])]),
            self.data_frame(3, "p3", src=self.S1),
        ]
        r = self.simulate(make_config(), events)
        self.assertEqual(r["results"][1]["action"], "mld_invalid")
        self.assertEqual(r["results"][2]["action"], "flood")
        self.assertEqual([g["group"] for g in r["groups"]], [G2])

    def test_bad_record_type(self):
        r = self.simulate(make_config(), [self.v2(1, "p2", [(7, G1, [])])])
        self.assertEqual(r["results"][0]["action"], "mld_invalid")

    def test_multicast_source_invalid(self):
        r = self.simulate(
            make_config(), [self.v2(1, "p2", [(1, G1, ["ff02::9"])])]
        )
        self.assertEqual(r["results"][0]["action"], "mld_invalid")

    def test_count_mismatch(self):
