            make_config(),
            [self.v2(1, "p2", [(1, G1, [self.S1])], truncate=2)],
        )
        self.assertEqual(r["results"][0]["action"], "mld_invalid")

    def test_v1_and_v2_coexist(self):
        events = [self.report(1, "p3"),
                  self.v2(2, "p2", [(2, G1, [self.S1])])]
        r = self.simulate(make_config(membership_age=50), events)
        members = r["groups"][0]["members"]
        self.assertEqual([m["name"] for m in members], ["p2", "p3"])
        self.assertEqual(list(members[0]),
                         ["name", "expires", "mode", "sources"])
        self.assertEqual(list(members[1]), ["name", "expires"])


class MldRecordTest(MldCase):
    def test_record_replay_byte_identical(self):
        events = [self.report(1, "p2"), self.data_frame(2, "p3")]
        self.write(make_config(), events)
        code, direct, err = self.run_cmd(
            "mld-snoop-decode", self.cfg, self.evt
        )
        self.assertEqual(code, 0, err)
        rec = subprocess.run(
            [sys.executable, SWITCH, "record", self.cfg, self.evt, self.log],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
        )
        self.assertEqual(rec.returncode, 0, rec.stderr)
        self.assertEqual(rec.stdout, direct)
        code, out, err = self.run_cmd("replay", self.log)
        self.assertEqual((code, out, err), (0, direct, b""))
        with open(self.log, "rb") as h:
            doc = json.loads(h.read().decode())
        self.assertEqual(doc["config"]["mld"]["router_ports"], ["p1"])

    def test_work_boundary(self):
        # B=1 L=0 P=4: stp 部分 1+5+6=12；N*(N+P+1)=2*7=14；合计 26
        events = [self.report(1, "p2"), self.data_frame(2, "p3")]
        self.write(make_config(), events)
        head = ("1048576", "16777216", "100000", "16777216")
        code, _, err = self.run_cmd(
            "mld-snoop-decode", self.cfg, self.evt, *head, "26"
        )
        self.assertEqual(code, 0, err)
        code, out, err = self.run_cmd(
            "mld-snoop-decode", self.cfg, self.evt, *head, "25"
        )
        self.assertEqual(code, 5)
        self.assertEqual(out, b"")
        self.assertEqual(err, b'{"error":"mld_work_limit"}\n')

    def test_bad_config_exit_4(self):
        bad = make_config()
        bad["mld"] = {"membership_age": 0, "router_ports": ["p1"]}
        self.write(bad, [])
        code, out, err = self.run_cmd("mld-snoop-decode", self.cfg, self.evt)
        self.assertEqual((code, out), (4, b""))
        self.assertEqual(err, b'{"error":"invalid_input"}\n')

    def test_record_bad_config_no_log(self):
        bad = make_config()
        bad["mld"] = {"membership_age": -1, "router_ports": ["p1"]}
        self.write(bad, [])
        code, out, err = self.run_cmd("record", self.cfg, self.evt, self.log)
        self.assertEqual((code, out), (4, b""))
        self.assertFalse(os.path.exists(self.log))


if __name__ == "__main__":
    unittest.main()

